// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Paper, type PaperProps } from "@/components/ui/paper";
import { usePaperDecor } from "@/hooks/use-paper-object";
import { napkinRecipe, type NapkinFold } from "@/lib/ink/recipes/napkin-ink";
import { cn } from "@/lib/utils";
type NapkinProps = Omit<PaperProps, "stock" | "rules"> & {
  fold?: NapkinFold;
  stain?: boolean;
};
const Napkin = defineUi<NapkinProps>("Napkin", ["class", "fold", "stain", "seed", "tilt", "size", "style"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const children = renderValue(() => readSlot(_slots.default));
  const ref = computed(() => _props["ref"]);
  const fold = computed(() => _props["fold"] === undefined ? "quarter" as const : _props["fold"]);
  const stain = computed(() => _props["stain"] === undefined ? false : _props["stain"]);
  const seed = computed(() => _props["seed"]);
  const tilt = computed(() => _props["tilt"]);
  const size = computed(() => _props["size"]);
  const style = computed(() => _props["style"]);
  const props = computed(() => omitProps(_props, ["class", "children", "ref", "fold", "stain", "seed", "tilt", "size", "style"]));
  const o = usePaperDecor(() => ({
    recipe: napkinRecipe,
    params: {
      fold: fold.value,
      stain: stain.value
    },
    kind: "napkin" as const,
    ref: ref.value,
    seed: seed.value,
    tilt: tilt.value,
    tiltMax: 1.2,
    size: size.value,
    enabled: fold.value !== "none" || stain.value
  }));
  return () => {
    return <Paper data-slot="napkin" data-fold={fold.value} stock="napkin" rules="none" size={size.value} {...domProps(o.value.paper)} {...domProps(props.value)} class={cn(o.value.paper.className, "flex min-h-56 w-72 flex-col gap-2 p-9 text-ink", className.value)} style={cssStyle({
      ...o.value.paper.style,
      ...style.value
    })}>
      {o.value.decor}
      {readSlot(_slots.default)}
    </Paper>;
  };
});
const NapkinContent = defineUi<UI.ComponentProps<"div">>("NapkinContent", ["class"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const props = computed(() => omitProps(_props, ["class"]));
  return () => {
    return <div data-slot="napkin-content" class={cn("flex-1 font-script text-[1.5rem] leading-[1.15]", className.value)} {...domProps(props.value)}>{_slots.default?.()}</div>;
  };
});
const NapkinTitle = defineUi<UI.ComponentProps<"div">>("NapkinTitle", ["class"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const props = computed(() => omitProps(_props, ["class"]));
  return () => {
    return <div data-slot="napkin-title" class={cn("font-script text-[2rem] leading-none font-bold", className.value)} {...domProps(props.value)}>{_slots.default?.()}</div>;
  };
});
const NapkinFooter = defineUi<UI.ComponentProps<"div">>("NapkinFooter", ["class"], (_props, {
  slots: _slots
}) => {
  const className = computed(() => _props["class"]);
  const props = computed(() => omitProps(_props, ["class"]));
  return () => {
    return <div data-slot="napkin-footer" class={cn("mt-auto text-sm text-ink-soft", className.value)} {...domProps(props.value)}>{_slots.default?.()}</div>;
  };
});
export { Napkin, NapkinTitle, NapkinContent, NapkinFooter };
export type { NapkinProps };

import { coffeeRing } from '@/lib/ink/paper/props'
import { defineRecipe } from '@/lib/ink/recipes'
import { num, pathTag, tok } from '@/lib/ink/recipes/paper-set-ink'

export type NapkinFold = 'quarter' | 'half' | 'none'

export interface NapkinParams {
  fold: NapkinFold
  stain: boolean
}

export const napkinRecipe = defineRecipe<NapkinParams>({
  id: 'napkin-decor',
  kind: 'napkin',
  layers: ['rest'],
  pad: 4,
  draw(ink, { w, h }, { fold, stain }, ctx) {
    const r = ink.next('creases')
    const id = `ll-nk${ink.seed.toString(36)}`
    ink.layer('rest', () => {
      let s = ''
      const reach = 34
      const vertical = (x0: number, i: number) => {
        const j = r.gauss(0, 0.5)
        s += `<linearGradient id="${id}v${i}" x1="1" y1="0" x2="0" y2="0"><stop offset="0" stop-color="${tok('ink')}" stop-opacity=".085"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity="0"/></linearGradient>`
        s += pathTag(`M${num(x0 - reach)} 0H${num(x0)}V${num(h)}H${num(x0 - reach)}z`, { fill: `url(#${id}v${i})`, transform: `translate(${num(j)} 0)` })
        s += pathTag(`M${num(x0 + j)} 3L${num(x0 + j + r.gauss(0, 0.6))} ${num(h * 0.5)}L${num(x0 + j)} ${num(h - 3)}`, { stroke: tok('ink'), sw: 0.7, op: 0.2 })
        s += pathTag(`M${num(x0 + j + 1.2)} 3L${num(x0 + j + 1.2)} ${num(h - 3)}`, { stroke: tok('photo'), sw: 1, op: 0.75 })
      }
      const horizontal = (y0: number, i: number) => {
        const j = r.gauss(0, 0.5)
        s += `<linearGradient id="${id}h${i}" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="${tok('ink')}" stop-opacity=".085"/><stop offset="1" stop-color="${tok('ink')}" stop-opacity="0"/></linearGradient>`
        s += pathTag(`M0 ${num(y0 - reach)}H${num(w)}V${num(y0)}H0z`, { fill: `url(#${id}h${i})`, transform: `translate(0 ${num(j)})` })
        s += pathTag(`M3 ${num(y0 + j)}L${num(w * 0.5)} ${num(y0 + j + r.gauss(0, 0.6))}L${num(w - 3)} ${num(y0 + j)}`, { stroke: tok('ink'), sw: 0.7, op: 0.2 })
        s += pathTag(`M3 ${num(y0 + j + 1.2)}H${num(w - 3)}`, { stroke: tok('photo'), sw: 1, op: 0.75 })
      }
      if (fold === 'quarter') {
        vertical(w / 2 + r.gauss(0, 0.4), 0)
        horizontal(h / 2 + r.gauss(0, 0.4), 0)
      } else if (fold === 'half') horizontal(h / 2 + r.gauss(0, 0.4), 0)
      if (stain) {
        const R = Math.min(46, Math.max(24, Math.min(w, h) * 0.13))
        const ring = coffeeRing(`${ink.seed}|ring`, { radius: R, tier: ink.tier, calm: ctx.calm })
        s += `<g transform="translate(${num(w * 0.58)} ${num(h * 0.56)}) rotate(${num(r.range(-30, 30))} ${num(R)} ${num(R)})">${ring.svg}</g>`
      }
      ink.raw(s, 'top')
      ink.grow([0, 0, w, h])
    })
  },
})
